export function seedAllDeletionOwnedRows(
  db: DatabaseSync,
  i: DeletionSeedIdentity,
) {
  for (const { table, values, shared } of deletionOwnedSeedRows(i)) {
    if (shared && db.prepare(`SELECT 1 FROM ${table} LIMIT 1`).get()) continue;
    const columns = Object.keys(values),
      parameters = Object.values(values);
    try {
      db.prepare(
        `INSERT OR IGNORE INTO ${table} (${columns.join(",")}) VALUES (${columns.map(() => "?").join(",")})`,
      ).run(...parameters);
    } catch (error) {
      throw new Error(`Deletion fixture could not seed ${table}`, {
        cause: error,
      });
    }
  }
  seedDeletionReceiptVariants(db, i);
  db.prepare(
    "INSERT OR IGNORE INTO deleted_project_redaction_values (value) VALUES ('global-ledger-private')",
  ).run();
  if (!db.prepare("SELECT 1 FROM project_tombstones LIMIT 1").get()) {
    const projectId = i.uuid("prior-deleted-project"),
      deletedAt = "2026-11-04T00:00:00.000Z";
    db.prepare(
      "INSERT INTO project_tombstones VALUES (?,?,?,'operator',?,?,?,?,?,?,'complete')",
    ).run(
      projectId,
      "Prior deleted",
      deletedAt,
      JSON.stringify({ tasks: 0, assignments: 0, worktrees: 0 }),
      "[]",
      i.uuid("prior-delete-key"),
      "a".repeat(64),
      JSON.stringify({ kind: "project-deleted", projectId, deletedAt }),
      JSON.stringify({ version: 1, items: [] }),
    );
  }
  db.prepare(
    "UPDATE diagnostic_executions SET payloadBytes=(SELECT COALESCE(SUM(payloadBytes),0) FROM diagnostic_items WHERE diagnostic_items.workId=diagnostic_executions.workId)",
  ).run();
  db.prepare(
    "UPDATE diagnostic_usage SET totalBytes=(SELECT COALESCE(SUM(payloadBytes),0) FROM diagnostic_items) WHERE id=1",
  ).run();
}
